CREATE TABLE organizations(id uuid PRIMARY KEY, name varchar(200) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, email varchar(254) NOT NULL UNIQUE, password_hash text NOT NULL, verified boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_members(organization_id uuid REFERENCES organizations, user_id uuid REFERENCES users, role text NOT NULL CHECK(role IN ('ADMIN','RECRUITER','EVALUATOR','CANDIDATE')), PRIMARY KEY(organization_id,user_id));
CREATE TABLE verification_tokens(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE assessments(id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, title varchar(200) NOT NULL, author_id uuid NOT NULL REFERENCES users, status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')), content jsonb NOT NULL, revision bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id));
CREATE TABLE assessment_versions(id uuid PRIMARY KEY, organization_id uuid NOT NULL, assessment_id uuid NOT NULL, version integer NOT NULL, content jsonb NOT NULL, published_by uuid NOT NULL REFERENCES users, published_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,assessment_id) REFERENCES assessments(organization_id,id), UNIQUE(assessment_id,version), UNIQUE(organization_id,id));
CREATE TABLE invitations(id uuid PRIMARY KEY, organization_id uuid NOT NULL, assessment_version_id uuid NOT NULL, email varchar(254) NOT NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false, claimed_by uuid REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,assessment_version_id) REFERENCES assessment_versions(organization_id,id), UNIQUE(organization_id,id));
CREATE TABLE assessment_attempts(id uuid PRIMARY KEY, organization_id uuid NOT NULL, invitation_id uuid NOT NULL UNIQUE, candidate_id uuid NOT NULL REFERENCES users, status text NOT NULL CHECK(status IN ('IN_PROGRESS','SUBMITTED','EXPIRED')), started_at timestamptz NOT NULL, last_activity_at timestamptz NOT NULL, accounted_at timestamptz NOT NULL, consumed_ms bigint NOT NULL DEFAULT 0 CHECK(consumed_ms>=0), pause_ms bigint NOT NULL DEFAULT 0, pause_count integer NOT NULL DEFAULT 0, outage_open boolean NOT NULL DEFAULT false, deadline timestamptz NOT NULL, lease_id uuid NOT NULL, lease_until timestamptz NOT NULL, revision bigint NOT NULL DEFAULT 0, current_question uuid, submitted_at timestamptz, FOREIGN KEY(organization_id,invitation_id) REFERENCES invitations(organization_id,id), UNIQUE(organization_id,id));
CREATE INDEX attempts_expiry_idx ON assessment_attempts(status,deadline);
CREATE TABLE candidate_answers(attempt_id uuid REFERENCES assessment_attempts, question_id uuid NOT NULL, answer jsonb NOT NULL, revision bigint NOT NULL, saved_at timestamptz NOT NULL, PRIMARY KEY(attempt_id,question_id));
CREATE TABLE answer_revisions(attempt_id uuid REFERENCES assessment_attempts, revision bigint NOT NULL, question_id uuid NOT NULL, answer jsonb NOT NULL, saved_at timestamptz NOT NULL, PRIMARY KEY(attempt_id,revision));
CREATE TABLE mutation_receipts(attempt_id uuid REFERENCES assessment_attempts, key uuid NOT NULL, payload_hash text NOT NULL, revision bigint NOT NULL, PRIMARY KEY(attempt_id,key));
CREATE TABLE attempt_timer_events(id bigserial PRIMARY KEY, attempt_id uuid REFERENCES assessment_attempts, event text NOT NULL, active_ms bigint NOT NULL, paused_ms bigint NOT NULL, occurred_at timestamptz NOT NULL);
CREATE TABLE evaluation_results(attempt_id uuid PRIMARY KEY REFERENCES assessment_attempts, organization_id uuid NOT NULL REFERENCES organizations, final_revision bigint NOT NULL, baseline jsonb NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY, recipient text NOT NULL, subject text NOT NULL, body text NOT NULL, state text NOT NULL DEFAULT 'QUEUED', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id bigserial PRIMARY KEY, organization_id uuid REFERENCES organizations, actor_id uuid REFERENCES users, action text NOT NULL, resource_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_scope_idx ON audit_events(organization_id,occurred_at);
CREATE INDEX invitation_scope_idx ON invitations(organization_id,email);
CREATE TABLE ai_jobs(id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, requester_id uuid NOT NULL REFERENCES users, purpose text NOT NULL CHECK(purpose IN ('COMPETENCY','QUESTION','FEEDBACK','REPORT')), idempotency_key uuid NOT NULL, payload_hash text NOT NULL, input jsonb NOT NULL, state text NOT NULL DEFAULT 'QUEUED', attempts integer NOT NULL DEFAULT 0, reservation integer NOT NULL, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), failure_code text, UNIQUE(organization_id,requester_id,idempotency_key), UNIQUE(organization_id,id));
CREATE INDEX ai_queue_idx ON ai_jobs(state,available_at);
CREATE TABLE ai_artifacts(id uuid PRIMARY KEY, organization_id uuid NOT NULL, job_id uuid NOT NULL UNIQUE, author_id uuid NOT NULL REFERENCES users, purpose text NOT NULL, content jsonb NOT NULL, provenance jsonb NOT NULL, state text NOT NULL DEFAULT 'REVIEW_REQUIRED', revision bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,job_id) REFERENCES ai_jobs(organization_id,id), UNIQUE(organization_id,id));
CREATE TABLE ai_review_decisions(id uuid PRIMARY KEY, organization_id uuid NOT NULL, artifact_id uuid NOT NULL, reviewer_id uuid NOT NULL REFERENCES users, decision text NOT NULL CHECK(decision IN ('APPROVED','REJECTED')), reason text NOT NULL, expected_revision bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,artifact_id) REFERENCES ai_artifacts(organization_id,id));
CREATE TABLE ai_usage_ledger(organization_id uuid PRIMARY KEY REFERENCES organizations, reserved_units bigint NOT NULL DEFAULT 0, spent_units bigint NOT NULL DEFAULT 0, CHECK(reserved_units>=0), CHECK(spent_units>=0));
CREATE TABLE candidate_review_requests(id uuid PRIMARY KEY, candidate_id uuid NOT NULL REFERENCES users, attempt_id uuid NOT NULL REFERENCES assessment_attempts, reason text NOT NULL, state text NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE candidate_acknowledgments(invitation_id uuid PRIMARY KEY REFERENCES invitations, candidate_id uuid NOT NULL REFERENCES users, disclosure_version text NOT NULL, optional_ai boolean NOT NULL, system_checks jsonb NOT NULL, acknowledged_at timestamptz NOT NULL DEFAULT now());
-- Published snapshots are append-only, including for administrators using application SQL.
CREATE FUNCTION reject_snapshot_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'published versions are immutable'; END $$;
CREATE TRIGGER immutable_assessment BEFORE UPDATE OR DELETE ON assessment_versions FOR EACH ROW EXECUTE FUNCTION reject_snapshot_mutation();
